    ["Червоноградський район"] = "Шептицький район",
}

local sin, floor = math.sin, math.floor
local function min(a, b) if a < b then return a end return b end
local function max(a, b) if a > b then return a end return b end
local function clamp(x, a, b) return min(b, max(a, x)) end
local function rgb(r, g, b) return display.color565(floor(clamp(r, 0, 255)), floor(clamp(g, 0, 255)), floor(clamp(b, 0, 255))) end
local function mix(a, b, k) return { a[1] + (b[1] - a[1]) * k, a[2] + (b[2] - a[2]) * k, a[3] + (b[3] - a[3]) * k } end

local W, H
local OX, OY
local t = 0
local next_fetch = 1
local levels, at = {}, nil -- levels[i]: 0 — спокійно, 1 — жовта, 2 — червона
local ended = {}           -- ended[i] = час відбою, щоб показати його кілька хвилин
local reason               -- причина тривоги у вашому районі, якщо її дає API
local source               -- звідки останні дані
local status
local home

local BG = { 10, 12, 20 }
local CALM = { 38, 58, 84 }
local LEVEL = { { 245, 190, 40 }, { 225, 45, 45 } }
local DIM = { { 140, 100, 20 }, { 120, 20, 28 } }
local CLEAR = { 60, 200, 120 }
local WORDS = { "жовта", "червона" }

-- Прямокутники закодовано по 2 символи на число (base64), 8 символів на прямокутник.
-- Їх кілька тисяч, тож вони лишаються рядками і розбираються під час малювання.
local B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local IDX = {}
for i = 1, #B64 do IDX[B64:byte(i)] = i - 1 end

local by_name = {}
local OCCUPIED = {} -- тут тривога не знімається з 2022 року, тож у лічильник не йде
local function norm(s) return (s:gsub("\u{2019}", "'"):gsub("\u{2BC}", "'")) end

local function save()
    local digits = {}
    for i = 1, #REGIONS do digits[i] = tostring(levels[i] or 0) end
    local text = "at=" .. at .. "\nlevels=" .. table.concat(digits) .. "\nsource=" .. (source or "")
    if reason then text = text .. "\nreason=" .. reason end
    pcall(resources.write_file, CACHE, text)
end

local function load()
    local ok, text = pcall(resources.read_file, CACHE)
    if not ok or not text then return end
    local a, digits = text:match("at=(%d+)"), text:match("levels=([012]+)")
    if not (a and digits and #digits == #REGIONS) then return end
    at = tonumber(a)
    for i = 1, #REGIONS do levels[i] = tonumber(digits:sub(i, i)) end
    source = text:match("source=([^\n]+)")
    reason = text:match("reason=([^\n]+)")
end

-- Обидва API віддають масив об'єктів з назвою (району, області чи громади) і рівнем.
-- Тривога на всю область фарбує всі її райони, громади без району пропускаються.
local function parse(body)
    local now, why, n = {}, nil, 0
    for obj in body:gmatch("{[^{}]*}") do
        local name = obj:match('"name_uk":"([^"]*)"') or obj:match('"name":"([^"]*)"')
        local lvl = obj:match('"level":"(%a+)"')
        if name and lvl then
            n = n + 1
            local v = lvl == "red" and 2 or lvl == "yellow" and 1 or 0
            name = norm(name)
            name = OLD_NAMES[name] or name
            local i = by_name[name]
            local hit = {}
            if i then
                hit[1] = i
            else
                for o, oname in ipairs(OBLASTS) do
                    if oname == name then
                        for j, r in ipairs(REGIONS) do
                            if r.oblast == o then hit[#hit + 1] = j end
                        end
                    end
                end
            end
            for _, j in ipairs(hit) do
                now[j] = max(now[j] or 0, v)
                if j == home then
                    local r = obj:match('"reasons":%["([^"]*)"')
                    if r then why = r:gsub(" %(.*%)$", "") end
                end
            end
        end
    end
    -- Порожній список — теж відповідь (тривог немає), а от без масиву це не наш JSON
    if n == 0 and not body:find('"alerts":%[') and not body:find('"raions":%[') then return nil end
    return now, why
end

local function apply(now, why)
    for i = 1, #REGIONS do
        local v = now[i] or 0
        if (levels[i] or 0) > 0 and v == 0 and at then ended[i] = os.time() end
        if v > 0 then ended[i] = nil end
        levels[i] = v
    end
    reason = home and levels[home] > 0 and why or nil
    at = os.time()
    save()
end

local function fetch()
    if not (http and wifi) or wifi.get_status() ~= 3 then
        status = "Wi-Fi не під'єднано"
        return
    end
    status = "Не вдалося завантажити"
    for _, src in ipairs(SOURCES) do
        collectgarbage()
        local ok, res = pcall(http.execute, { url = src.url })
        if ok and res.code == 200 and res.response then
            local now, why = parse(res.response)
            if now then
                source = src.name
                apply(now, why)
                status = nil
                return
            end
            status = "Незрозуміла відповідь"
        end
    end
end

function lilka.init()
    W, H = display.width, display.height
    -- Застосунок стартує на весь екран, тож display.height = 240 навіть з fullscreen = false
    if not lilka.fullscreen and H > 216 then H = H - 24 end
    OX, OY = floor((W - MAP_W) / 2), H - MAP_H - 4
    for i, r in ipairs(REGIONS) do by_name[r.name] = i end
    for o, name in ipairs(OBLASTS) do
        if name == "Автономна Республіка Крим" or name == "Севастополь" or name == "Луганська область" then OCCUPIED[o] = true end
    end
    home = by_name[HOME]
    load()
end

function lilka.update(delta)
    t = t + delta
    next_fetch = next_fetch - delta
    if next_fetch <= 0 then
        next_fetch = REFRESH
        fetch()
    end
    if controller then
        local st = controller.get_state()
        if st.a.just_pressed then next_fetch = REFRESH; fetch() end
        if st.start.just_pressed then util.exit() end
    end
end

local function text(x, y, s, c, font)
    display.set_font(font or "6x13")
    display.set_text_size(1)
    display.set_text_color(c)
    display.set_cursor(floor(x), floor(y))
    display.print(s)
end

local function fill(s, c)
    for i = 1, #s, 8 do
        local a, b, c1, d, e, f, g, h = s:byte(i, i + 7)
        display.fill_rect(OX + IDX[a] * 64 + IDX[b], OY + IDX[c1] * 64 + IDX[d], IDX[e] * 64 + IDX[f], IDX[g] * 64 + IDX[h], c)
    end
end

local function hm(ts)
    local d = os.date("*t", ts)
    return string.format("%02d:%02d", d.hour, d.min)
end

local function short(name)
    return (name:gsub(" район$", " р-н"):gsub("^м%. ", ""))
end

function lilka.draw()
    display.fill_screen(rgb(BG[1], BG[2], BG[3]))
    local now = os.time()
    local stale = not at or now - at > STALE
    local hx, hy = home and REGIONS[home].cx or 0, home and REGIONS[home].cy or 0

    fill(SILHOUETTE, rgb(4, 6, 10))
    local count = { 0, 0 }
    for i, r in ipairs(REGIONS) do
        local c = CALM
        local v = levels[i] or 0
        if v > 0 then
            if not OCCUPIED[r.oblast] then count[v] = count[v] + 1 end
            -- Хвиля пульсації розходиться від вашого району
            local d = ((r.cx - hx) ^ 2 + (r.cy - hy) ^ 2) ^ 0.5
            c = mix(LEVEL[v], DIM[v], 0.5 + 0.5 * sin(t * 3 - d * 0.04))
        elseif ended[i] and now - ended[i] < 600 then
            c = mix(CLEAR, CALM, (now - ended[i]) / 600)
        end
        if stale then c = mix(c, { 70, 70, 76 }, 0.6) end
        fill(r.rects, rgb(c[1], c[2], c[3]))
    end
    fill(BORDERS, rgb(120, 135, 165))

    if home then
        local v = levels[home] or 0
        local rad = 4 + (t * 6) % 10
        local k = 1 - (rad - 4) / 10
        local hc = v > 0 and LEVEL[v] or CLEAR
        display.draw_circle(OX + hx, OY + hy, floor(rad), rgb(hc[1] * k + BG[1], hc[2] * k + BG[2], hc[3] * k + BG[3]))
        display.fill_circle(OX + hx, OY + hy, 2, rgb(255, 255, 255))
    end

    local white, grey = rgb(240, 244, 255), rgb(140, 150, 175)
    local red, yellow, green = rgb(255, 110, 100), rgb(255, 205, 70), rgb(110, 220, 150)
    text(8, 16, "Повітряна тривога", white, "8x13")
    text(W - 38, 16, hm(now), white, "8x13")
    if at then
        if count[1] + count[2] == 0 then
            text(8, 30, "Тривог немає", green, "6x12")
        else
            -- "Райони: червона N, жовта M", кожен шматок своїм кольором
            local x = 8
            local parts = { { "Райони: ", grey } }
            if count[2] > 0 then parts[#parts + 1] = { "червона " .. count[2], red } end
            if count[2] > 0 and count[1] > 0 then parts[#parts + 1] = { ", ", grey } end
            if count[1] > 0 then parts[#parts + 1] = { "жовта " .. count[1], yellow } end
            for _, p in ipairs(parts) do
                text(x, 30, p[1], p[2], "6x12")
                x = x + 6 * utf8.len(p[1])
            end
        end
        if home then
            local v = levels[home] or 0
            local hs = short(HOME) .. ": " .. (v > 0 and WORDS[v] or "відбій")
            if v > 0 and reason then hs = hs .. ", " .. reason end
            text(8, H - 30, hs, v == 2 and red or v == 1 and yellow or green, "6x12")
        end
        text(8, H - 16, (stale and "застаріло, " or "") .. "о " .. hm(at) .. ", дані: " .. (source or "?"), grey, "6x12")
    else
        text(8, 30, "Немає даних", white, "6x12")
    end
    if status and (controller or not at) then text(8, H - 4, status, rgb(255, 120, 100), "6x12") end
end
